function parseVN(v) { const m = String(v ?? '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? new Date(Date.UTC(+m[1], m[2] - 1, +m[3])) : null; }
function pad2(n) { return String(n).padStart(2, '0'); }
function fmtVN(d) { return d ? pad2(d.getUTCDate()) + '/' + pad2(d.getUTCMonth() + 1) + '/' + d.getUTCFullYear() : ''; }
function fmtISO(d) { return d ? d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate()) : ''; }
function addDays(d, n) { return new Date(d.getTime() + Number(n || 0) * 86400000); }

// Ứng viên đã hired nhưng chưa có hồ sơ nhân viên (DB đã lọc): dựng sẵn checklist và lộ trình đào tạo.
const r = $input.first().json;
const today = parseVN(r.today);
const catalog = Array.isArray(r.catalog) ? r.catalog : [];
const byId = Object.fromEntries(catalog.map(c => [c.course_id, c]));
const skipped = [];
const packages = [];

for (const c of (Array.isArray(r.pending) ? r.pending : [])) {
  if (!c.email) { skipped.push({ candidate_id: c.candidate_id, reason: 'thiếu email' }); continue; }
  if (c.email_taken) { skipped.push({ candidate_id: c.candidate_id, reason: 'email đã thuộc một nhân viên khác' }); continue; }

  // Ngày bắt đầu = ngày hồ sơ chuyển sang hired (lấy từ lịch sử trạng thái), như bản Sheets.
  const start = parseVN(c.hired_on) || today;
  const tasks = (c.templates || []).map(t => {
    let due = addDays(start, t.due_offset_days);
    // Việc chuẩn bị (offset âm) có thể rơi vào quá khứ: dồn hạn về hôm nay thay vì để quá hạn sẵn.
    if (due.getTime() < today.getTime()) due = today;
    return {
      template_id: t.template_id, task_name: t.task_name, category: t.category,
      owner_role: t.owner_role, due_date: fmtISO(due), course_id: t.course_id || '',
    };
  });

  const seen = new Set();
  const trainings = [];
  for (const t of tasks) {
    if (!t.course_id || seen.has(t.course_id)) continue;
    seen.add(t.course_id);
    const crs = byId[t.course_id] || {};
    trainings.push({
      course_id: t.course_id, source: 'template', assigned_on: fmtISO(start), due_on: t.due_date,
      cost_vnd: crs.cost_vnd ?? '', note: 'Gán tự động theo checklist mẫu của vị trí.',
      course_name: crs.course_name || '', material_url: crs.material_url || '',
    });
  }

  const skills = Array.isArray(c.skills_to_verify) ? c.skills_to_verify.join('; ') : '';
  const ai_prompt = [
    'Bạn là trợ lý nhân sự của công ty ABC Tech. Nhiệm vụ: gợi ý lộ trình đào tạo cho nhân viên mới.',
    '',
    'THÔNG TIN NHÂN VIÊN:',
    '- Họ tên: ' + (c.full_name || ''),
    '- Vị trí: ' + (c.job_title || c.declared_role || ''),
    '- Phòng ban: ' + (c.department || ''),
    '- Kỹ năng cần xác minh: ' + (skills || 'không ghi'),
    '- Tóm tắt CV: ' + String(c.ai_summary || 'không ghi').slice(0, 600),
    '',
    'DANH MỤC KHÓA HỌC CÓ SẴN (chỉ được chọn trong danh sách này):',
    JSON.stringify(catalog.map(x => ({ course_id: x.course_id, course_name: x.course_name, skill: x.skill, job_id: x.job_id || '', level: x.level || '', prerequisite_course_id: x.prerequisite_course_id || '', duration_hours: x.duration_hours })), null, 1),
    '',
    'KHÓA ĐÃ GÁN SẴN THEO MẪU ONBOARDING: ' + (trainings.map(t => t.course_id).join(', ') || 'không có'),
    '',
    'YÊU CẦU:',
    '1. Chỉ dùng course_id có thật trong danh mục trên. TUYỆT ĐỐI không bịa khóa học mới.',
    '2. Đề xuất tối đa 2 khóa BỔ SUNG ngoài các khóa đã gán sẵn (có thể để mảng rỗng nếu không cần).',
    '3. KHÔNG đề xuất khóa advanced nếu khóa prerequisite_course_id của nó chưa nằm trong danh sách đã gán.',
    '4. Ưu tiên khóa basic lấp khoảng trống kỹ năng mềm nếu nhân viên đã đủ khóa chuyên môn.',
    '5. Viết nhận xét lộ trình ngắn gọn, tối đa 60 từ, bằng tiếng Việt.',
    '',
    'Trả về DUY NHẤT một object JSON, không kèm giải thích, không kèm markdown:',
    '{"extra_course_ids": ["CRS-00X"], "plan_note": "..."}',
  ].join('\n');

  packages.push({ json: {
    _noop: false,
    candidate_id: c.candidate_id, full_name: c.full_name, email: c.email,
    job_id: c.job_id, job_title: c.job_title || '', department: c.department || '',
    manager: c.hiring_manager || '', buddy: '', is_sample: !!c.is_sample,
    start_date: fmtISO(start), start_date_vn: fmtVN(start),
    tasks, trainings, catalog_ids: catalog.map(x => x.course_id), ai_prompt,
  } });
}

if (packages.length === 0) {
  return [{ json: { _noop: true, skipped, message: 'Không có ứng viên hired nào chờ onboarding.' } }];
}
packages[0].json._skipped = skipped;
return packages;

function parseVN(v) { const m = String(v ?? '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? new Date(Date.UTC(+m[1], m[2] - 1, +m[3])) : null; }
function pad2(n) { return String(n).padStart(2, '0'); }
function fmtISO(d) { return d ? d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate()) : ''; }
function addDays(d, n) { return new Date(d.getTime() + Number(n || 0) * 86400000); }

// Nhận kết quả AI, chỉ giữ course_id có thật trong danh mục, gộp vào lộ trình đào tạo.
const src = $('A · Đọc ứng viên chờ onboarding (PG)').first().json;
const settings = src.settings || {};
const byId = Object.fromEntries((src.catalog || []).map(c => [c.course_id, c]));
const pkgs = $('Dựng gói onboarding').all().map(i => i.json);

let aiItems = [];
try { aiItems = $('AI: gợi ý lộ trình đào tạo').all(); } catch (e) { aiItems = []; }

return pkgs.map((p0, i) => {
  const p = JSON.parse(JSON.stringify(p0));
  let planNote = '';
  let extras = [];
  let aiStatus = 'off';

  if (settings.training_ai !== false && aiItems[i]) {
    aiStatus = 'ok';
    const raw = String(aiItems[i].json.text || aiItems[i].json.response || aiItems[i].json.output || '');
    const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
    const a = cleaned.indexOf('{');
    const b = cleaned.lastIndexOf('}');
    try {
      if (a < 0 || b < 0) throw new Error('không tìm thấy JSON');
      const parsed = JSON.parse(cleaned.slice(a, b + 1));
      planNote = String(parsed.plan_note || '').trim();
      const allowed = new Set(p.catalog_ids);
      const already = new Set(p.trainings.map(t => t.course_id));
      extras = (Array.isArray(parsed.extra_course_ids) ? parsed.extra_course_ids : [])
        .map(x => String(x).trim())
        .filter(x => allowed.has(x) && !already.has(x))
        .slice(0, 2);
    } catch (e) {
      aiStatus = 'fallback';
      planNote = 'AI trả về không đúng định dạng — giữ nguyên lộ trình theo mẫu onboarding.';
      extras = [];
    }
  }

  const start = parseVN(p.start_date);
  for (const cid of extras) {
    const crs = byId[cid] || {};
    p.trainings.push({
      course_id: cid, source: 'ai_suggested', assigned_on: p.start_date, due_on: fmtISO(addDays(start, 14)),
      cost_vnd: crs.cost_vnd ?? '', note: 'AI đề xuất bổ sung (Workflow 2).',
      course_name: crs.course_name || '', material_url: crs.material_url || '',
    });
  }
  return { json: { ...p, ai_status: aiStatus, ai_extra_ids: extras, plan_note: planNote } };
});

const d = $input.first().json;
const skipped = d.skipped || [];
return [{ json: { logs: [{
  entity_id: '', event: 'no_new_hire', level: 'skipped',
  message: 'Không có ứng viên hired nào chờ onboarding.'
    + (skipped.length ? ' Bỏ qua: ' + skipped.map(s => s.candidate_id + ' (' + s.reason + ')').join('; ') : ''),
}] } }];

function parseVN(v) { const m = String(v ?? '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? new Date(Date.UTC(+m[1], m[2] - 1, +m[3])) : null; }
function pad2(n) { return String(n).padStart(2, '0'); }
function fmtVN(d) { return d ? pad2(d.getUTCDate()) + '/' + pad2(d.getUTCMonth() + 1) + '/' + d.getUTCFullYear() : ''; }
function hienThiNgay(v) { const d = parseVN(v); return d ? fmtVN(d) : String(v || ''); }

const settings = $('A · Đọc ứng viên chờ onboarding (PG)').first().json.settings || {};
const pkgs = $('Chuẩn hóa gợi ý AI').all().map(i => i.json);
const saved = $input.all().map(i => i.json);
const out = [];

pkgs.forEach((d, i) => {
  const r = saved[i] || {};
  if (!r.employee_id) return;   // ứng viên đã có hồ sơ nhân viên từ lần chạy trước
  const lines = d.tasks
    .map((t, k) => (k + 1) + '. ' + t.task_name + '  —  hạn ' + hienThiNgay(t.due_date) + ' (phụ trách: ' + t.owner_role + ')')
    .join('\n');
  const trainLines = d.trainings
    .map(t => '- ' + t.course_id + ' ' + (t.course_name || '') + ' — hạn ' + hienThiNgay(t.due_on)
      + (t.material_url ? '\n  Tài liệu: ' + t.material_url : ''))
    .join('\n');

  const body = [
    'Chào ' + d.full_name + ',',
    '',
    'Chào mừng bạn gia nhập ABC Tech ở vị trí ' + (d.job_title || d.job_id) + '.',
    '',
    'Mã nhân viên: ' + r.employee_id,
    'Ngày bắt đầu: ' + d.start_date_vn,
    '',
    'CHECKLIST ONBOARDING (' + d.tasks.length + ' đầu việc):',
    lines,
    '',
    'LỘ TRÌNH ĐÀO TẠO (' + d.trainings.length + ' khóa):',
    trainLines || '- (chưa có khóa nào)',
    d.plan_note ? '\nGợi ý lộ trình: ' + d.plan_note : '',
    '',
    'Quản lý và buddy sẽ liên hệ với bạn trong ngày làm việc đầu tiên.',
    '',
    '---',
    'Email tự động từ hệ thống HR (Workflow 2).',
  ].join('\n');

  out.push({ json: {
    send: settings.wf2_dry_run !== true,
    to: settings.wf2_send_to_real_email === false ? (settings.demo_email || settings.hr_notify_email) : d.email,
    subject: 'Chào mừng ' + d.full_name + ' — thông tin onboarding (' + r.employee_id + ')',
    body,
    employee_id: r.employee_id,
  } });
});
return out;

const settings = $('A · Đọc ứng viên chờ onboarding (PG)').first().json.settings || {};
const pkgs = $('Chuẩn hóa gợi ý AI').all().map(i => i.json);
const saved = $('A · Tạo nhân viên, checklist, đào tạo (PG)').all().map(i => i.json);
const skipped = $('Dựng gói onboarding').first().json._skipped || [];

const logs = pkgs.map((d, i) => {
  const r = saved[i] || {};
  if (!r.employee_id) {
    return { entity_id: d.candidate_id, event: 'onboarding_skipped', level: 'skipped',
      message: d.candidate_id + ' đã có hồ sơ nhân viên, không tạo lại.' };
  }
  return { entity_id: r.employee_id, event: 'onboarding_created', level: 'success',
    message: 'Tạo ' + r.employee_id + ' (' + d.full_name + ', ' + d.job_id + ') từ ' + d.candidate_id + ' với '
      + r.task_count + ' đầu việc, ' + r.training_count + ' khóa đào tạo. AI: ' + d.ai_status
      + (d.ai_extra_ids.length ? ' (+' + d.ai_extra_ids.join(',') + ')' : '') + '.'
      + (settings.wf2_dry_run === true ? ' Chạy thử: không gửi email.' : '') };
});
for (const s of skipped) {
  logs.push({ entity_id: s.candidate_id, event: 'onboarding_skipped', level: 'warning',
    message: 'Bỏ qua ' + s.candidate_id + ': ' + s.reason + '.' });
}
return [{ json: { logs } }];

function parseVN(v) { const m = String(v ?? '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? new Date(Date.UTC(+m[1], m[2] - 1, +m[3])) : null; }
function pad2(n) { return String(n).padStart(2, '0'); }
function fmtISO(d) { return d ? d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate()) : ''; }
function addDays(d, n) { return new Date(d.getTime() + Number(n || 0) * 86400000); }
function diffDays(a, b) { return Math.round((a.getTime() - b.getTime()) / 86400000); }
function toInt(v) { const n = parseInt(String(v ?? '').replace(/[^0-9-]/g, ''), 10); return isNaN(n) ? 0 : n; }
// Chữ ký link trong email: không cho người ngoài đoán mã đầu việc khác để bấm bừa (mức bảo vệ cho bài demo).
function kyLink(id, secret) {
  const s = String(id).toUpperCase() + '|' + String(secret);
  let a = 5381, b = 2166136261;
  for (let i = 0; i < s.length; i++) { a = ((a * 33) ^ s.charCodeAt(i)) >>> 0; b = ((b ^ s.charCodeAt(i)) * 16777619) >>> 0; }
  return (a.toString(36) + b.toString(36)).slice(0, 16);
}
function nhanLink(base, path, id, secret) { return String(base).replace(/\/+$/, '') + '/' + path + '?t=' + encodeURIComponent(id) + '&k=' + kyLink(id, secret); }

// Quét tiến độ onboarding: tìm việc trễ / vướng / sắp hạn, đồng bộ quyền công cụ và khoá đào tạo.
const r = $input.first().json;
// HR bấm "Nhắc" trên cổng HR: chỉ quét người đó và gửi luôn, bỏ qua thời gian nghỉ giữa hai lần nhắc.
const force = r.force === true;
const s = r.settings || {};
const today = parseVN(r.today);
const tasks = r.tasks || [];
const employees = r.employees || [];
const trainings = r.trainings || [];
const warn = toInt(s.reminder_warn_days ?? 3);
const cooldown = toInt(s.reminder_cooldown_days ?? 2);
const cooldownBlocked = toInt(s.blocked_cooldown_days ?? 3);

const remindIds = [];
const groups = new Map();
for (const t of tasks) {
  // submitted = nhân viên đã nộp kết quả, đang chờ HR duyệt. Không nhắc nữa.
  if (t.status === 'done' || t.status === 'submitted') continue;

  const due = parseVN(t.due_date);
  let kind = null;
  let late = 0;
  if (t.status === 'blocked') kind = 'blocked';
  else if (due) {
    late = diffDays(today, due);
    if (late > 0) kind = 'overdue';
    else if (-late <= warn) kind = 'soon';
  }
  if (!kind) continue;

  const last = parseVN(t.last_reminded_on);
  if (!force && last && diffDays(today, last) < (kind === 'blocked' ? cooldownBlocked : cooldown)) continue;
  remindIds.push(t.task_id);

  // Việc của chính nhân viên thì nhắc nhân viên (kèm nút báo cáo).
  // Việc của HR, IT, buddy, quản lý thì gửi HR theo dõi, không làm phiền người mới.
  const audience = t.owner_role === 'employee' ? 'employee' : 'manager';
  const key = t.employee_id + '|' + audience;
  if (!groups.has(key)) groups.set(key, { employee_id: t.employee_id, audience, overdue: [], blocked: [], soon: [] });
  groups.get(key)[kind].push({
    task_id: t.task_id, task_name: t.task_name, category: t.category || '', due_date: t.due_date,
    owner_role: t.owner_role, late_days: late,
    url: audience === 'employee' ? nhanLink(s.webhook_base, 'bao-cao-task-pg', t.task_id, s.link_secret) : '',
  });
}

// Quyền công cụ: mọi đầu việc nhóm access đã xong thì confirmed.
const employeeUpdates = [];
for (const e of employees) {
  const access = tasks.filter(t => t.employee_id === e.employee_id && t.category === 'access');
  if (!access.length) continue;
  const tools = access.every(t => t.status === 'done') ? 'confirmed' : 'pending';
  if (tools !== e.tools_access) employeeUpdates.push({ employee_id: e.employee_id, tools_access: tools });
}

// Khoá đào tạo hoàn tất khi mọi đầu việc gắn khoá đó đã xong.
const trainingUpdates = [];
for (const tr of trainings) {
  const linked = tasks.filter(t => t.employee_id === tr.employee_id && t.course_id === tr.course_id);
  if (!linked.length || !linked.every(t => t.status === 'done')) continue;
  const comp = linked.map(t => parseVN(t.completed_on)).filter(Boolean).sort((a, b) => b - a)[0] || today;
  const validity = toInt(tr.validity_days);
  trainingUpdates.push({
    training_id: tr.training_id, completed_on: fmtISO(comp),
    certificate_expires_on: validity > 0 ? fmtISO(addDays(comp, validity)) : '',
  });
}

const reminders = [];
for (const g of groups.values()) {
  const e = employees.find(x => x.employee_id === g.employee_id);
  if (e) reminders.push({ ...g, full_name: e.full_name, email: e.email, manager: e.manager, buddy: e.buddy, department: e.department });
}

return [{ json: {
  settings: s,
  db: { today: r.today, remind_task_ids: remindIds, employees: employeeUpdates, trainings: trainingUpdates },
  reminders,
  summary: {
    scanned_tasks: tasks.length, flagged: remindIds.length, employees_changed: employeeUpdates.length,
    training_completed: trainingUpdates.length, emails: reminders.length,
    emails_nhan_vien: reminders.filter(x => x.audience === 'employee').length,
    emails_quan_ly: reminders.filter(x => x.audience === 'manager').length,
  },
} }];

function parseVN(v) { const m = String(v ?? '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? new Date(Date.UTC(+m[1], m[2] - 1, +m[3])) : null; }
function pad2(n) { return String(n).padStart(2, '0'); }
function fmtVN(d) { return d ? pad2(d.getUTCDate()) + '/' + pad2(d.getUTCMonth() + 1) + '/' + d.getUTCFullYear() : ''; }
function hienThiNgay(v) { const d = parseVN(v); return d ? fmtVN(d) : String(v || ''); }
function esc(v) { return String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function khungMail(than) { return '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#1f2328;max-width:580px">' + than + '</div>'; }

function nutNho(url, chu, mau) {
  return '<table cellpadding="0" cellspacing="0" border="0" style="margin:16px 0 4px"><tr><td '
    + 'style="background:' + mau + ';border-radius:8px">'
    + '<a href="' + esc(url) + '" style="display:inline-block;padding:13px 30px;'
    + 'font-family:Arial,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;'
    + 'text-decoration:none">' + esc(chu) + '</a></td></tr></table>';
}

const d = $('Quét tiến độ onboarding').first().json;
const s = d.settings || {};
const reminders = d.reminders || [];

// --- một ô đầu việc kèm nút, dùng cho mail gửi nhân viên
function oCoNut(t, nhan, mau) {
  return '<div style="border:1px solid #e3e6ea;border-radius:10px;padding:16px 18px;margin:0 0 14px">'
    + '<div style="font-size:12px;color:#8a929c;letter-spacing:.4px">' + esc(t.task_id)
    + (t.category ? ' · ' + esc(t.category) : '') + '</div>'
    + '<div style="font-size:16px;font-weight:bold;margin:4px 0 8px">' + esc(t.task_name) + '</div>'
    + '<div>Hạn ' + esc(hienThiNgay(t.due_date)) + ' — <b style="color:' + mau + '">' + nhan + '</b></div>'
    + (t.url ? nutNho(t.url, 'Báo cáo đầu việc', '#f86a56') : '')
    + '</div>';
}
// --- dòng trơn, dùng cho mail gửi HR (không có nút)
function dongTron(t) {
  return '<li style="margin:0 0 6px">' + esc(t.task_name)
    + ' <span style="color:#6b7280">(' + esc(t.task_id) + ', hạn ' + esc(hienThiNgay(t.due_date))
    + ', phụ trách ' + esc(t.owner_role) + ')</span>'
    + (t.late_days > 0 ? ' — <b style="color:#c23b2e">trễ ' + t.late_days + ' ngày</b>' : '')
    + '</li>';
}
function khoiTron(tieuDe, arr) {
  if (!arr || !arr.length) return '';
  return '<p style="margin:16px 0 6px"><b>' + esc(tieuDe) + '</b></p>'
    + '<ul style="margin:0;padding-left:20px">' + arr.map(dongTron).join('') + '</ul>';
}
const chanTrang = '<p style="color:#8a929c;font-size:12px;border-top:1px solid #e3e6ea;'
  + 'padding-top:12px;margin-top:20px">Email tự động từ hệ thống HR (Workflow 2). '
  + 'Vui lòng không trả lời email này.</p>';

return reminders.map(r => {
  const soon = r.soon || [];
  const tong = r.overdue.length + r.blocked.length + soon.length;
  let subject, body, nguoiNhan;

  if (r.audience === 'employee') {
    nguoiNhan = r.email;
    subject = r.overdue.length
      ? '[Quá hạn] ' + tong + ' đầu việc onboarding của bạn cần báo cáo'
      : '[Nhắc việc] ' + tong + ' đầu việc onboarding sắp tới hạn';
    body = khungMail(
      '<p>Chào ' + esc(r.full_name) + ',</p>'
      + '<p>Bạn có <b>' + tong + ' đầu việc onboarding</b> cần xử lý. '
      + 'Làm xong hay chưa xong đều bấm nút trong từng ô để báo lại.</p>'
      + r.overdue.map(t => oCoNut(t, 'đã quá hạn ' + t.late_days + ' ngày', '#c23b2e')).join('')
      + r.blocked.map(t => oCoNut(t, 'đang vướng, cần hỗ trợ', '#c23b2e')).join('')
      + soon.map(t => oCoNut(t,
          t.late_days === 0 ? 'hết hạn hôm nay' : 'còn ' + (-t.late_days) + ' ngày nữa là hết hạn',
          '#b07400')).join('')
      + '<p style="color:#6b7280;font-size:13px">Bấm <b>Đã hoàn thành</b> thì bạn nộp kèm '
      + 'tệp hoặc link kết quả. HR xem xong mới duyệt, và bạn sẽ nhận email báo kết quả.</p>'
      + '<p style="color:#6b7280;font-size:13px">Chưa kịp làm thì chọn <b>Chưa xong</b> và ghi lý do. '
      + 'Hệ thống ghi nhận là đang xử lý, không tính là bỏ bê.</p>'
      + '<p style="color:#6b7280;font-size:13px">Cần hỗ trợ thì liên hệ quản lý '
      + esc(r.manager || '(chưa gán)') + ' hoặc buddy ' + esc(r.buddy || '(chưa gán)') + '.</p>'
      + chanTrang);
  } else {
    nguoiNhan = s.hr_notify_email || r.email;
    subject = '[Nhắc việc] ' + tong + ' đầu việc onboarding của ' + r.employee_id
      + ' đang chờ bộ phận phụ trách';
    body = khungMail(
      '<p>Kính gửi ' + esc(r.manager || 'quản lý trực tiếp') + ' và các bộ phận liên quan,</p>'
      + '<p>Các đầu việc sau thuộc trách nhiệm của HR, IT, Buddy hoặc quản lý, phục vụ quá trình '
      + 'onboarding của nhân viên <b>' + esc(r.full_name) + '</b> ('
      + esc(r.employee_id) + ', ' + esc(r.department || 'chưa rõ phòng ban') + '):</p>'
      + khoiTron('Việc đã quá hạn', r.overdue)
      + khoiTron('Việc đang vướng (blocked)', r.blocked)
      + khoiTron('Việc sắp tới hạn', soon)
      + '<p style="margin-top:16px">Nhân viên không nhận được email này. Đề nghị bộ phận phụ trách '
      + 'xử lý sớm để không ảnh hưởng tiến độ hòa nhập của người mới.</p>'
      + chanTrang);
  }

  return { json: {
    send: s.wf2_dry_run !== true,
    to: s.wf2_send_to_real_email === false ? (s.demo_email || s.hr_notify_email) : nguoiNhan,
    subject, body, employee_id: r.employee_id, audience: r.audience,
  } };
});

const d = $('Quét tiến độ onboarding').first().json;
const s = d.summary;
return [{ json: { logs: [{
  entity_id: '', event: 'progress_scan', level: (d.settings || {}).wf2_dry_run === true ? 'info' : 'success',
  message: 'Quét ' + s.scanned_tasks + ' đầu việc; ' + s.flagged + ' việc trễ/vướng/sắp hạn; '
    + s.employees_changed + ' nhân viên đổi trạng thái quyền công cụ; ' + s.training_completed
    + ' khóa đào tạo hoàn tất; ' + s.emails + ' email nhắc việc ('
    + s.emails_nhan_vien + ' cho nhân viên, ' + s.emails_quan_ly + ' cho HR).'
    + ((d.settings || {}).wf2_dry_run === true ? ' Chạy thử: không gửi email.' : ''),
}] } }];

function parseVN(v) { const m = String(v ?? '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? new Date(Date.UTC(+m[1], m[2] - 1, +m[3])) : null; }
function diffDays(a, b) { return Math.round((a.getTime() - b.getTime()) / 86400000); }
function toInt(v) { const n = parseInt(String(v ?? '').replace(/[^0-9-]/g, ''), 10); return isNaN(n) ? 0 : n; }

// Nhân viên đủ số ngày thử việc, xong checklist và xong đào tạo thì chuyển chính thức.
const r = $input.first().json;
const s = r.settings || {};
const today = parseVN(r.today);
const NGAY_THU_VIEC = toInt(s.probation_days) || 90;
const employees = r.employees || [];

const duDieuKien = [];
const chuaDu = [];
for (const e of employees) {
  const start = parseVN(e.start_date);
  if (!start) continue;
  const soNgay = diffDays(today, start);
  const conLai = e.task_total - e.task_done;
  const khoaConLai = e.course_total - e.course_done;

  const lyDo = [];
  if (soNgay < NGAY_THU_VIEC) lyDo.push('mới ' + soNgay + '/' + NGAY_THU_VIEC + ' ngày');
  if (e.task_total === 0) lyDo.push('chưa có checklist onboarding');
  else if (conLai > 0) lyDo.push('còn ' + conLai + ' đầu việc chưa xong');
  if (khoaConLai > 0) lyDo.push('còn ' + khoaConLai + ' khóa đào tạo chưa hoàn tất');

  const ho = { ...e, so_ngay: soNgay };
  if (lyDo.length === 0) duDieuKien.push(ho);
  else chuaDu.push({ ...ho, ly_do: lyDo.join('; ') });
}

return [{ json: {
  settings: s,
  du_dieu_kien: duDieuKien,
  chua_du: chuaDu,
  ids: duDieuKien.map(x => x.employee_id),
  summary: { dang_thu_viec: employees.length, du_dieu_kien: duDieuKien.length, chua_du: chuaDu.length },
} }];

parameters.query:
with u as (
  update public.employees set employment_status = 'official'
  where employee_id in (select jsonb_array_elements_text($1::jsonb)) and employment_status = 'probation'
  returning employee_id
)
select count(*)::int as updated, coalesce(jsonb_agg(employee_id), '[]'::jsonb) as employee_ids from u;

