function parseVN(v) { const m = String(v ?? '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? new Date(Date.UTC(+m[1], m[2] - 1, +m[3])) : null; }
function pad2(n) { return String(n).padStart(2, '0'); }
function fmtVN(d) { return d ? pad2(d.getUTCDate()) + '/' + pad2(d.getUTCMonth() + 1) + '/' + d.getUTCFullYear() : ''; }
function hienThiNgay(v) { const d = parseVN(v); return d ? fmtVN(d) : String(v || ''); }

const d = $('Quét hết thử việc').first().json;
const s = d.settings || {};
const doiXong = new Set($input.first().json.employee_ids || []);
