}] } }];

const VN_OFFSET_MS = 7 * 3600000;
function parseVN(v) { const m = String(v ?? '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? new Date(Date.UTC(+m[1], m[2] - 1, +m[3])) : null; }
function pad2(n) { return String(n).padStart(2, '0'); }
function fmtVN(d) { return d ? pad2(d.getUTCDate()) + '/' + pad2(d.getUTCMonth() + 1) + '/' + d.getUTCFullYear() : ''; }
function hienThiNgay(v) { const d = parseVN(v); return d ? fmtVN(d) : String(v || ''); }
function diffDays(a, b) { return Math.round((a.getTime() - b.getTime()) / 86400000); }
function homNayVN() { const vn = new Date(Date.now() + VN_OFFSET_MS); return new Date(Date.UTC(vn.getUTCFullYear(), vn.getUTCMonth(), vn.getUTCDate())); }
// Chữ ký link trong email: không cho người ngoài đoán mã đầu việc khác để bấm bừa (mức bảo vệ cho bài demo).
function kyLink(id, secret) {
  const s = String(id).toUpperCase() + '|' + String(secret);
  let a = 5381, b = 2166136261;
  for (let i = 0; i < s.length; i++) { a = ((a * 33) ^ s.charCodeAt(i)) >>> 0; b = ((b ^ s.charCodeAt(i)) * 16777619) >>> 0; }
  return (a.toString(36) + b.toString(36)).slice(0, 16);
}
// Webhook nhiều phương thức có nhiều cổng ra (GET, POST): dò từng cổng, cổng nào có dữ liệu thì lấy.
function itemWebhook(ten) {
  const n = $(ten);
  for (let i = 0; i < 5; i++) { try { const a = n.all(i); if (a && a.length) return a[0]; } catch (e) { /* cổng rỗng */ } }
  try { const f = n.first(); if (f) return f; } catch (e) { /* không có gì */ }
  return { json: {}, binary: {} };
}
function esc(v) { return String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function trangHTML(tieuDe, than) {
  return '<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
    + '<title>' + esc(tieuDe) + '</title><style>*{box-sizing:border-box}'
    + 'body{margin:0;padding:32px 16px;background:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;color:#1f2328}'
    + '.hop{max-width:560px;margin:0 auto;background:#fff;border-radius:14px;box-shadow:0 2px 14px rgba(0,0,0,.08);padding:28px}'
    + 'h1{font-size:20px;margin:0 0 4px}.phu{color:#6b7280;font-size:13px;margin:0 0 20px}'
    + '.bang{width:100%;border-collapse:collapse;margin:0 0 20px;font-size:14px}'
    + '.bang td{padding:8px 0;border-bottom:1px solid #eceef1;vertical-align:top}.bang td:first-child{color:#6b7280;width:130px}'
    + 'textarea,input[type=text]{width:100%;padding:10px;border:1px solid #d6d9de;border-radius:8px;font:inherit;font-size:14px}'
    + 'textarea{min-height:76px;resize:vertical}'
    + 'input[type=file]{width:100%;padding:12px;border:1px dashed #c3c8cf;border-radius:8px;background:#fafbfc;font-size:13px}'
    + '.o{margin:0 0 16px}.bao-nhac{background:#fff6e5;color:#7a5200}label{display:block;font-size:13px;color:#6b7280;margin:0 0 6px}'
    + '.nut{display:inline-block;border:0;border-radius:8px;padding:14px 26px;font-size:15px;font-weight:700;color:#fff;cursor:pointer;text-decoration:none;margin:14px 10px 0 0}'
    + '.cam{background:#f86a56}.xanh{background:#17a36a}.xam{background:#8a929c}.do{background:#e0483a}'
    + '.bao{padding:14px 16px;border-radius:10px;font-size:14px;margin:0 0 18px}'
