    + '</style></head><body><div class="hop">' + than + '</div></body></html>';
}
function dongBang(nhan, giaTri) { return '<tr><td>' + esc(nhan) + '</td><td>' + esc(giaTri) + '</td></tr>'; }
function trangLoi(thongBao) {
  return trangHTML('Không mở được', '<h1>Không mở được phiếu này</h1><div class="bao bao-loi">' + esc(thongBao) + '</div>'
    + '<p class="phu">Nếu bạn vừa bấm nút trong email, hãy bấm lại đúng nút mới nhất, hoặc báo HR để được gửi lại.</p>');
}

const db = $input.first().json;
const s = db.settings || {};
const itWh = itemWebhook('Webhook nhân viên');
const req = itWh.json || {};

// n8n đặt dữ liệu form POST ở chỗ khác nhau tùy phiên bản và tùy kiểu mã hóa.
// Gom hết mọi chỗ có thể, chỗ nào có thì lấy, không phụ thuộc một đường duy nhất.
function gomTS(o, sau) {
  const ra = {};
  if (!o || typeof o !== 'object') return ra;
  for (const k of Object.keys(o)) {
    const v = o[k];
    if (v !== null && typeof v === 'object' && !Array.isArray(v) && (sau || 0) < 2) {
      Object.assign(ra, gomTS(v, (sau || 0) + 1));   // body.data, body.fields...
    } else {
      ra[k] = Array.isArray(v) ? v[v.length - 1] : v;  // nút gửi trùng tên thì lấy cái cuối
    }
  }
  return ra;
}
const p = Object.assign({}, gomTS(req.query), gomTS(req.params), gomTS(req.body));

const ma = String(p.t || '').trim().toUpperCase();
const chuKy = String(p.k || '').trim();
const ketQua = String(p.r || '').trim().toLowerCase();
const ghiChu = String(p.note || '').trim();
const linkDan = String(p.link || '').trim();

// Đếm tệp. Trình duyệt vẫn gửi phần tệp rỗng khi không chọn gì nên phải lọc.
const binAll = itWh.binary || {};
const soTep = Object.keys(binAll).filter(k => binAll[k] && (binAll[k].fileName || binAll[k].data)).length;
// Phòng trường hợp n8n không bóc được tệp ra phần nhị phân mà để tên tệp trong body.
const coTep = soTep > 0 || Object.keys(p).some(k => /^tep/i.test(k) && String(p[k] || '').trim() !== '');

const dung = (html) => [{ json: { _stage: 'dung', _html: html, _upload: false } }];

if (!ma) return dung(trangLoi('Link thiếu mã đầu việc.'));
if (chuKy !== kyLink(ma, s.link_secret)) return dung(trangLoi('Link không hợp lệ hoặc đã bị sửa.'));

const t = db.task;
if (!t) return dung(trangLoi('Không tìm thấy đầu việc ' + ma + '.'));
const emp = db.employee || {};
const due = parseVN(t.due_date);
const conLai = due ? diffDays(due, parseVN(db.today) || homNayVN()) : null;

const thongTin = '<table class="bang">'
  + dongBang('Mã đầu việc', t.task_id)
  + dongBang('Nhân viên', (emp.full_name || t.employee_id) + ' (' + t.employee_id + ')')
  + dongBang('Nội dung', t.task_name)
  + dongBang('Hạn', hienThiNgay(t.due_date)
      + (conLai === null ? '' : (conLai > 0 ? '  ·  còn ' + conLai + ' ngày'
        : (conLai === 0 ? '  ·  hết hạn hôm nay' : '  ·  quá hạn ' + Math.abs(conLai) + ' ngày'))))
  + '</table>';

if (t.status === 'done') {
  return dung(trangHTML('Đầu việc đã xong',
    '<h1>Đầu việc này đã hoàn tất</h1>'
    + '<div class="bao bao-ok">HR đã duyệt xong đầu việc này, bạn không cần báo lại.</div>'
    + thongTin));
}
if (t.status === 'submitted') {
  return dung(trangHTML('Đang chờ HR',
    '<h1>Đang chờ HR duyệt</h1>'
    + '<div class="bao bao-cho">Bạn đã nộp kết quả đầu việc này. '
    + 'HR đang kiểm tra, kết quả sẽ gửi về email của bạn.</div>'
    + thongTin));
}

// ---------- trang form ----------
function trangForm(canhBao) {
  const act = String(s.webhook_base).replace(/\/+$/, '') + '/bao-cao-task-pg';
  return trangHTML('Báo cáo đầu việc',
    '<h1>Báo cáo đầu việc</h1>'
    + '<p class="phu">Nộp kết quả để HR xem rồi duyệt. Kết quả ghi thẳng vào hệ thống HR.</p>'
    + thongTin
    + (t.hr_review === 'returned' && t.hr_note ? '<div class="bao bao-loi">HR đã trả lại lần trước: ' + esc(t.hr_note) + '</div>' : '')
