    + '<textarea id="note" name="note" placeholder="Ví dụ: đã đọc xong tài liệu kiến trúc và ghi chú lại 5 điểm chính về quy trình code review.">'
    + esc(ghiChu) + '</textarea></div>'
    + '<div class="o"><label for="tep">Tệp bằng chứng — ảnh chụp màn hình, PDF, tài liệu. '
    + 'Tối đa 3 tệp, mỗi tệp dưới 10 MB</label>'
    + '<input id="tep" type="file" name="tep" multiple></div>'
    + '<div class="o"><label for="link">Hoặc dán link kết quả — pull request, Google Doc, bản ghi màn hình…</label>'
    + '<input id="link" type="text" name="link" placeholder="https://..." value="' + esc(linkDan) + '"></div>'
