    + '<button class="nut xam" type="submit" name="r" value="chua">Chưa xong</button>'
    + '</form>');
}

if (ketQua !== 'done' && ketQua !== 'chua') return dung(trangForm(''));

// ---------- báo xong thì bắt buộc có bằng chứng ----------
if (ketQua === 'done' && s.require_proof !== false && !coTep && !linkDan) {
  return dung(trangForm('Báo "Đã hoàn thành" thì phải nộp ít nhất một tệp hoặc dán một link. '
    + 'HR cần xem được kết quả mới duyệt được.'));
}

return [{ json: {
  _stage: 'ghi',
  _html: '',
  _upload: ketQua === 'done' && soTep > 0,
  ma, chuKy, ketQua, ghiChu, linkDan, soTep,
  thongTin,
  drive_folder_id: s.proof_drive_folder_id || 'root',
  employee_id: t.employee_id,
  task: {
    task_id: t.task_id, task_name: t.task_name, category: t.category,
    employee_id: t.employee_id, employee_name: emp.full_name || t.employee_id,
    employee_email: String(emp.email || '').trim(),
    department: emp.department || '', manager: emp.manager || '',
    due_vn: hienThiNgay(t.due_date), course_id: t.course_id || '',
  },
} }];

// Webhook nhiều phương thức có nhiều cổng ra (GET, POST): dò từng cổng, cổng nào có dữ liệu thì lấy.
function itemWebhook(ten) {
  const n = $(ten);
  for (let i = 0; i < 5; i++) { try { const a = n.all(i); if (a && a.length) return a[0]; } catch (e) { /* cổng rỗng */ } }
  try { const f = n.first(); if (f) return f; } catch (e) { /* không có gì */ }
  return { json: {}, binary: {} };
}

const ctx = $('Kiểm tra báo cáo').first().json;
const bin = itemWebhook('Webhook nhân viên').binary || {};

// Mỗi tệp thành một item riêng, phần nhị phân đổi tên cố định là "tep"
// để node Google Drive biết lấy ở đâu.
const ra = [];
Object.keys(bin).slice(0, 3).forEach((k, i) => {
  const b = bin[k];
  if (!b || (!b.fileName && !b.data)) return;
  const duoi = b.fileExtension ? '.' + b.fileExtension : '';
  const goc = String(b.fileName || ('tep' + (i + 1) + duoi)).replace(/[\\/:*?"<>|]/g, '_');
  ra.push({
    json: { ten_tep: ctx.ma + '_' + ctx.employee_id + '_' + (i + 1) + '_' + goc, folder_id: ctx.drive_folder_id || 'root' },
    binary: { tep: b },
  });
});
return ra;

// Gom kết quả từ node Google Drive thành danh sách tệp (tên + link).
// Dựng link từ id nên không phụ thuộc Drive có trả webViewLink hay không.
const ds = items
  .map(i => i.json)
  .filter(x => x && x.id)
  .map(x => ({ name: x.name || 'tệp', url: 'https://drive.google.com/file/d/' + x.id + '/view' }));
return [{ json: { links: ds } }];

// Chữ ký link trong email: không cho người ngoài đoán mã đầu việc khác để bấm bừa (mức bảo vệ cho bài demo).
function kyLink(id, secret) {
  const s = String(id).toUpperCase() + '|' + String(secret);
  let a = 5381, b = 2166136261;
  for (let i = 0; i < s.length; i++) { a = ((a * 33) ^ s.charCodeAt(i)) >>> 0; b = ((b ^ s.charCodeAt(i)) * 16777619) >>> 0; }
  return (a.toString(36) + b.toString(36)).slice(0, 16);
}
function nhanLink(base, path, id, secret) { return String(base).replace(/\/+$/, '') + '/' + path + '?t=' + encodeURIComponent(id) + '&k=' + kyLink(id, secret); }
function esc(v) { return String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function trangHTML(tieuDe, than) {
  return '<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
    + '<title>' + esc(tieuDe) + '</title><style>*{box-sizing:border-box}'
    + 'body{margin:0;padding:32px 16px;background:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;color:#1f2328}'
    + '.hop{max-width:560px;margin:0 auto;background:#fff;border-radius:14px;box-shadow:0 2px 14px rgba(0,0,0,.08);padding:28px}'
    + 'h1{font-size:20px;margin:0 0 4px}.phu{color:#6b7280;font-size:13px;margin:0 0 20px}'
    + '.bang{width:100%;border-collapse:collapse;margin:0 0 20px;font-size:14px}'
    + '.bang td{padding:8px 0;border-bottom:1px solid #eceef1;vertical-align:top}.bang td:first-child{color:#6b7280;width:130px}'
    + 'textarea,input[type=text]{width:100%;padding:10px;border:1px solid #d6d9de;border-radius:8px;font:inherit;font-size:14px}'
    + 'textarea{min-height:76px;resize:vertical}'
    + 'input[type=file]{width:100%;padding:12px;border:1px dashed #c3c8cf;border-radius:8px;background:#fafbfc;font-size:13px}'
    + '.o{margin:0 0 16px}.bao-nhac{background:#fff6e5;color:#7a5200}label{display:block;font-size:13px;color:#6b7280;margin:0 0 6px}'
    + '.nut{display:inline-block;border:0;border-radius:8px;padding:14px 26px;font-size:15px;font-weight:700;color:#fff;cursor:pointer;text-decoration:none;margin:14px 10px 0 0}'
    + '.cam{background:#f86a56}.xanh{background:#17a36a}.xam{background:#8a929c}.do{background:#e0483a}'
    + '.bao{padding:14px 16px;border-radius:10px;font-size:14px;margin:0 0 18px}'
    + '.bao-ok{background:#e7f6ee;color:#17603f}.bao-loi{background:#fdeceb;color:#8c2c22}.bao-cho{background:#e8eefc;color:#1a3f8f}'
    + '</style></head><body><div class="hop">' + than + '</div></body></html>';
}
function dongBang(nhan, giaTri) { return '<tr><td>' + esc(nhan) + '</td><td>' + esc(giaTri) + '</td></tr>'; }
function dongBangHTML(nhan, html) { return '<tr><td>' + esc(nhan) + '</td><td>' + html + '</td></tr>'; }
// Danh sách "tên::url" (mỗi dòng một tệp) -> các thẻ <a> bấm được
function dsLink(chuoi, mauChu) {
  const ds = String(chuoi || '').split(/[\n|]+/).map(x => x.trim()).filter(Boolean);
  if (!ds.length) return '<span style="color:#8a929c">(không có)</span>';
  return ds.map(u => {
    const m = u.match(/^(.*?)::(.*)$/);
    return '<a href="' + esc(m ? m[2] : u) + '" target="_blank" rel="noopener" style="color:' + (mauChu || '#1a5fd0') + ';word-break:break-all">' + esc(m ? m[1] : u) + '</a>';
  }).join('<br>');
}

const s = $('G · Đọc đầu việc (PG)').first().json.settings || {};
const ctx = $('Kiểm tra báo cáo').first().json;

// Trang lỗi / trang form: trả thẳng, không ghi gì.
if (ctx._stage !== 'ghi') {
  return [{ json: { _html: ctx._html, _write: false, _mail: false } }];
}

// Tệp đã tải lên Drive. Không có tệp thì node đó không chạy, nên bọc try.
let tep = [];
try {
  const g = $('Gom link tệp').first();
  if (g && g.json && Array.isArray(g.json.links)) tep = g.json.links;
} catch (e) { /* không có tệp đính kèm */ }
const links = ctx.linkDan ? String(ctx.linkDan).split(/\s+/).filter(Boolean).map(u => ({ name: u, url: u })) : [];
const proof = tep.concat(links);
const proofText = proof.map(x => x.name + '::' + x.url).join('\n');

const xong = ctx.ketQua === 'done';
const row = {
  task_id: ctx.task.task_id,
  status: xong ? 'submitted' : 'in_progress',
  employee_note: ctx.ghiChu,
  proof_name: proof.map(x => x.name).join('\n'),
  proof_url: proof.map(x => x.url).join('\n'),
};

const bangKQ = (ctx.ghiChu || proof.length)
  ? '<table class="bang">'
    + (ctx.ghiChu ? dongBang('Bạn mô tả', ctx.ghiChu) : '')
    + (proof.length ? dongBangHTML('Đã nộp', dsLink(proofText)) : '')
    + '</table>'
  : '';

const html = xong
  ? trangHTML('Đã gửi cho HR',
      '<h1>Đã nhận kết quả, cảm ơn bạn</h1>'
      + '<div class="bao bao-ok">Kết quả đã gửi sang HR. Trạng thái đầu việc chuyển sang '
      + '<b>Chờ HR duyệt</b>. HR xem xong sẽ gửi email báo kết quả cho bạn.</div>'
      + ctx.thongTin + bangKQ)
  : trangHTML('Đã ghi nhận',
      '<h1>Đã ghi nhận là đang làm</h1>'
      + '<div class="bao bao-cho">Trạng thái đầu việc chuyển sang <b>đang làm</b>. '
      + 'Hệ thống sẽ nhắc lại khi gần hạn. Xong lúc nào bạn bấm lại nút trong email lúc đó.</div>'
      + ctx.thongTin + bangKQ);

return [{ json: {
  _html: html,
  _write: true,
  _mail: xong,                 // chỉ phiền HR khi nhân viên báo xong
  row,
  task: ctx.task,
  ghi_chu_nv: ctx.ghiChu,
  proof_text: proofText,
  so_tep: ctx.soTep,
  link_hr: nhanLink(s.webhook_base, 'hr-duyet-pg', ctx.task.task_id, s.link_secret),
} }];

function esc(v) { return String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
// Danh sách "tên::url" (mỗi dòng một tệp) -> các thẻ <a> bấm được
function dsLink(chuoi, mauChu) {
