const s = $('G · Đọc đầu việc (PG)').first().json.settings || {};
const d = $('Hoàn tất báo cáo').first().json;
const saved = $input.first().json;

// Chỉ mời HR khi nhân viên báo xong và DB đã ghi nhận (đầu việc chưa bị đổi trạng thái ở nơi khác).
if (!d._mail || !(Number(saved.updated) > 0)) return [{ json: { send: false } }];

