} }];

const d = $('Hoàn tất báo cáo').first().json;
const saved = $('G · Lưu báo cáo (PG)').first().json;
const t = d.task || {};
const r = d.row || {};
const ghi = Number(saved.updated) > 0;
return [{ json: { logs: [{
