}

const db = $input.first().json;
const s = db.settings || {};
const q = $('Webhook HR').first().json.query || {};

const ma = String(q.t || '').trim().toUpperCase();
const chuKy = String(q.k || '').trim();
const quyetDinh = String(q.act || '').trim().toLowerCase();
const lyDo = String(q.note || '').trim();

const khong = (msg) => [{ json: { _html: trangLoi(msg), _write: false, _mail: false } }];

if (!ma) return khong('Link thiếu mã đầu việc.');
if (chuKy !== kyLink(ma, s.link_secret)) return khong('Link không hợp lệ hoặc đã bị sửa.');

const t = db.task;
if (!t) return khong('Không tìm thấy đầu việc ' + ma + '.');
const emp = db.employee || {};

// Tên tệp và link lưu ở hai cột, mỗi dòng một tệp.
const ten = String(t.proof_name || '').split('\n');
const proofText = String(t.proof_url || '').split('\n').map((u, i) => u.trim() ? (ten[i] || u) + '::' + u.trim() : '').filter(Boolean).join('\n');

const thongTin = '<table class="bang">'
  + dongBang('Mã đầu việc', t.task_id)
  + dongBang('Nhân viên', (emp.full_name || t.employee_id) + ' (' + t.employee_id + ')')
  + dongBang('Bộ phận', emp.department || '')
  + dongBang('Nội dung', t.task_name)
  + dongBang('Hạn', hienThiNgay(t.due_date))
  + dongBang('NV báo xong ngày', t.submitted_at ? fmtVN(new Date(Date.parse(t.submitted_at) + VN_OFFSET_MS)) : '(chưa có)')
  + dongBang('Ghi chú của NV', String(t.employee_note || '') || '(không có)')
  + dongBangHTML('Kết quả đã nộp', dsLink(proofText))
  + '</table>';

if (t.status === 'done') {
  return [{ json: {
    _html: trangHTML('Đã duyệt rồi',
      '<h1>Đầu việc này đã được duyệt</h1>'
      + '<div class="bao bao-ok">Trạng thái hiện tại là <b>done</b>'
      + (t.hr_note ? '. Ghi chú duyệt: ' + esc(t.hr_note) : '') + '.</div>'
      + thongTin),
    _write: false, _mail: false } }];
}
if (t.status !== 'submitted') {
  return [{ json: {
    _html: trangHTML('Chưa có gì để duyệt',
      '<h1>Chưa có báo cáo nào chờ duyệt</h1>'
      + '<div class="bao bao-cho">Đầu việc đang ở trạng thái <b>' + esc(t.status)
      + '</b>. Nhân viên chưa bấm báo hoàn thành, nên chưa có gì để bạn duyệt.</div>'
      + thongTin),
    _write: false, _mail: false } }];
}

const act = String(s.webhook_base).replace(/\/+$/, '') + '/hr-duyet-pg';
// --- chưa chọn: hiện phiếu duyệt
if (quyetDinh !== 'approve' && quyetDinh !== 'reject') {
  return [{ json: {
    _html: trangHTML('Phiếu duyệt đầu việc',
      '<h1>Phiếu duyệt đầu việc</h1>'
      + '<p class="phu">Kiểm tra kết quả nhân viên nộp rồi chọn một trong hai nút.</p>'
      + thongTin
      + '<form method="get" action="' + esc(act) + '">'
      + '<input type="hidden" name="t" value="' + esc(t.task_id) + '">'
      + '<input type="hidden" name="k" value="' + esc(chuKy) + '">'
      + '<label for="note">Nhận xét gửi nhân viên — bắt buộc ghi nếu chọn Chưa đạt</label>'
      + '<textarea id="note" name="note" placeholder="Ví dụ: pull request còn thiếu phần kiểm thử, bổ sung rồi báo lại."></textarea>'
      + '<button class="nut xanh" type="submit" name="act" value="approve">Duyệt — đạt</button>'
      + '<button class="nut do" type="submit" name="act" value="reject">Chưa đạt</button>'
      + '</form>'),
    _write: false, _mail: false } }];
}

const dat = quyetDinh === 'approve';

// Chưa đạt mà không ghi lý do thì bắt ghi, nếu không nhân viên không biết sửa gì.
if (!dat && !lyDo) {
  return [{ json: {
    _html: trangHTML('Thiếu lý do',
      '<h1>Cần ghi lý do</h1>'
      + '<div class="bao bao-loi">Chọn <b>Chưa đạt</b> thì phải ghi nhận xét, '
      + 'nếu không nhân viên không biết phải sửa gì.</div>'
      + thongTin
      + '<form method="get" action="' + esc(act) + '">'
      + '<input type="hidden" name="t" value="' + esc(t.task_id) + '">'
      + '<input type="hidden" name="k" value="' + esc(chuKy) + '">'
      + '<label for="note">Nhận xét gửi nhân viên</label>'
      + '<textarea id="note" name="note"></textarea>'
      + '<button class="nut do" type="submit" name="act" value="reject">Gửi — Chưa đạt</button>'
      + '<button class="nut xanh" type="submit" name="act" value="approve">Đổi ý — Duyệt</button>'
      + '</form>'),
    _write: false, _mail: false } }];
}

const html = dat
  ? trangHTML('Đã duyệt',
      '<h1>Đã duyệt xong</h1>'
      + '<div class="bao bao-ok">Trạng thái đầu việc chuyển sang <b>done</b>. '
      + 'Email báo kết quả đã gửi cho nhân viên.</div>' + thongTin)
  : trangHTML('Đã trả lại',
      '<h1>Đã trả lại cho nhân viên</h1>'
      + '<div class="bao bao-loi">Trạng thái đầu việc quay về <b>đang làm</b>. '
      + 'Nhân viên đã nhận email kèm nhận xét của bạn.</div>'
      + thongTin
      + '<table class="bang">' + dongBang('Nhận xét đã gửi', lyDo) + '</table>');

return [{ json: {
  _html: html,
  _write: true,
  _mail: true,
  dat,
  ly_do: lyDo,
  row: { task_id: t.task_id, decision: dat ? 'approved' : 'returned', hr_note: lyDo },
  task: {
    task_id: t.task_id, task_name: t.task_name, category: t.category,
    employee_id: t.employee_id, employee_name: emp.full_name || t.employee_id,
    employee_email: String(emp.email || '').trim(),
    due_vn: hienThiNgay(t.due_date), course_id: t.course_id || '',
  },
} }];

function esc(v) { return String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function khungMail(than) { return '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#1f2328;max-width:580px">' + than + '</div>'; }

const s = $('H · Đọc đầu việc (PG)').first().json.settings || {};
const d = $('Xử lý duyệt').first().json;
const saved = $input.first().json;

if (!d._mail || !(Number(saved.updated) > 0)) return [{ json: { send: false } }];

const t = d.task;
const nguoiNhan = s.wf2_send_to_real_email === false ? (s.demo_email || s.hr_notify_email) : (t.employee_email || s.hr_notify_email);
const hop = (mau, chu) => '<div style="background:' + mau + ';border-radius:10px;padding:14px 16px;'
  + 'font-size:14px;margin:0 0 18px">' + chu + '</div>';
const chanTrang = '<p style="color:#8a929c;font-size:12px;border-top:1px solid #e3e6ea;padding-top:12px">'
  + 'ABC Tech · Email tự động từ hệ thống onboarding.</p>';

const body = d.dat
  ? khungMail(
      '<p>Chào ' + esc(t.employee_name) + ',</p>'
      + hop('#e7f6ee', '<b style="color:#17603f">HR đã duyệt đầu việc của bạn.</b> '
        + 'Đầu việc <b>' + esc(t.task_id) + '</b> chuyển sang trạng thái hoàn tất.')
      + '<p><b>' + esc(t.task_name) + '</b><br>'
      + '<span style="color:#6b7280;font-size:13px">Hạn ' + esc(t.due_vn) + '</span></p>'
      + (d.ly_do ? '<p style="color:#6b7280;font-size:13px">Nhận xét của HR: ' + esc(d.ly_do) + '</p>' : '')
      + '<p>Cảm ơn bạn đã báo cáo đúng hạn. Các đầu việc còn lại sẽ được nhắc khi gần tới hạn.</p>'
      + chanTrang)
  : khungMail(
      '<p>Chào ' + esc(t.employee_name) + ',</p>'
      + hop('#fdeceb', '<b style="color:#8c2c22">Đầu việc chưa đủ điều kiện hoàn thành.</b> '
        + 'HR đã xem kết quả của đầu việc <b>' + esc(t.task_id) + '</b> và trả lại để bạn bổ sung.')
      + '<p><b>' + esc(t.task_name) + '</b><br>'
      + '<span style="color:#6b7280;font-size:13px">Hạn ' + esc(t.due_vn) + '</span></p>'
      + '<p style="border-left:3px solid #e0483a;padding:4px 0 4px 14px;margin:16px 0">'
      + '<b>HR nhận xét:</b><br>' + esc(d.ly_do) + '</p>'
      + '<p>Bổ sung xong bạn bấm lại nút <b>Báo cáo đầu việc</b> trong email nhắc việc gần nhất. '
      + 'Trạng thái hiện đang là <b>đang làm</b>, chưa bị tính là bỏ bê.</p>'
      + chanTrang);

return [{ json: {
  send: s.wf2_dry_run !== true,
  to: nguoiNhan,
  subject: (d.dat ? '[Đã duyệt] ' : '[Cần bổ sung] ') + t.task_id + ' — ' + t.task_name,
  body,
} }];

const d = $('Xử lý duyệt').first().json;
const saved = $('H · Lưu kết quả duyệt (PG)').first().json;
const t = d.task || {};
const ghi = Number(saved.updated) > 0;
return [{ json: { logs: [{
  entity_id: t.task_id || '', event: d.dat ? 'hr_duyet_task' : 'hr_tra_lai_task', level: ghi ? 'success' : 'warning',
  message: 'HR ' + (d.dat ? 'DUYỆT' : 'TRẢ LẠI') + ' đầu việc ' + (t.task_id || '?')
    + ' của ' + (t.employee_name || '?')
    + (d.ly_do ? '. Nhận xét: ' + String(d.ly_do).replace(/\.$/, '') : '')
    + (ghi ? '.' : '. Không ghi được vì đầu việc không còn ở trạng thái chờ duyệt.'),
}] } }];
